import { apiRequest } from './client';

// The API only accepts these query params (anything else is a 400).
const LIST_PARAMS = ['page', 'limit', 'category', 'q', 'minPrice', 'maxPrice'];

export function listGigs(filters, signal) {
  const params = new URLSearchParams();
  for (const key of LIST_PARAMS) {
    const value = filters[key];
    if (value !== undefined && value !== null && value !== '') params.set(key, String(value));
  }
  const query = params.toString();
  return apiRequest(`/api/gigs${query ? `?${query}` : ''}`, { signal });
}

// Ids are 24 hex characters. Anything else is never put into a URL, so a
// crafted id like "../admin/users" can't change which endpoint is called.
export function isValidId(id) {
  return typeof id === 'string' && /^[a-f0-9]{24}$/i.test(id);
}

export function getGig(id, signal) {
  return apiRequest(`/api/gigs/${encodeURIComponent(id)}`, { signal });
}

// ---- Freelancer: their own gigs ----

export function listMyGigs(signal) {
  return apiRequest('/api/gigs/mine', { signal });
}

// Only these fields are sent; the API rejects anything else (including
// "freelancer", which it always takes from the token).
function gigBody({ title, description, price, category, deliveryDays }) {
  return { title, description, price, category, deliveryDays };
}

export function createGig(fields) {
  return apiRequest('/api/gigs', { method: 'POST', body: gigBody(fields) });
}

export function updateGig(id, fields) {
  return apiRequest(`/api/gigs/${encodeURIComponent(id)}`, { method: 'PUT', body: gigBody(fields) });
}

export function setGigActive(id, isActive) {
  return apiRequest(`/api/gigs/${encodeURIComponent(id)}`, { method: 'PUT', body: { isActive } });
}

// Resolves to { id, deleted, deactivated, message? } - a gig with bookings
// is deactivated instead of deleted.
export function deleteGig(id) {
  return apiRequest(`/api/gigs/${encodeURIComponent(id)}`, { method: 'DELETE' });
}

import { useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { adminDeleteGig } from '../api/admin';
import ConfirmAction from './ConfirmAction';

// Admin-only removal from the gig page. The API decides whether the gig is
// deleted or (if it has bookings) deactivated, and says which; that message
// is shown on the gig list afterwards.
export default function AdminDeleteGig({ gigId, title }) {
  const navigate = useNavigate();
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const busyRef = useRef(false);

  async function handleConfirm() {
    if (busyRef.current) return;
    busyRef.current = true;
    setBusy(true);
    setError('');
    try {
      const result = await adminDeleteGig(gigId);
      navigate('/gigs', { replace: true, state: { message: result.message } });
    } catch (err) {
      setError(err.status === 404 ? 'This gig no longer exists.' : err.message);
      busyRef.current = false;
      setBusy(false);
    }
  }

  if (!confirming) {
    return (
      <div>
        <button type="button" className="button danger" onClick={() => setConfirming(true)}>
          Delete as admin
        </button>
      </div>
    );
  }

  return (
    <ConfirmAction
      title="Delete this gig as admin?"
      confirmLabel="Delete gig"
      busyLabel="Deleting…"
      busy={busy}
      error={error}
      onConfirm={handleConfirm}
      onCancel={() => {
        setConfirming(false);
        setError('');
      }}
    >
      <p>
        <strong>{title}</strong> will be removed. If it has bookings it will be deactivated instead, so the booking
        and transaction history stays intact.
      </p>
    </ConfirmAction>
  );
}

import { useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { createBooking } from '../api/bookings';
import { formatMoney } from '../utils/format';

/**
 * Book -> confirm (simulated payment) -> done.
 *
 * Only { gigId } is sent: the API takes the price and freelancer from the
 * database. A ref guards against a double click booking twice, on top of
 * disabling the button while the request is in flight.
 */
export default function BookingPanel({ gigId, title, price, onUnavailable }) {
  const [step, setStep] = useState('idle'); // idle | confirm | sending | done
  const [error, setError] = useState('');
  const [reference, setReference] = useState('');
  const sendingRef = useRef(false);

  async function confirmBooking() {
    if (sendingRef.current) return;
    sendingRef.current = true;
    setStep('sending');
    setError('');

    try {
      const result = await createBooking(gigId);
      setReference(result.transaction.reference);
      setStep('done');
    } catch (err) {
      if (err.status === 404) {
        onUnavailable(); // the gig was removed or deactivated meanwhile
        return;
      }
      // 429 carries the API's "try again in N seconds" message; network
      // errors carry a generic connection message.
      setError(err.message);
      setStep('confirm');
    } finally {
      sendingRef.current = false;
    }
  }

  if (step === 'done') {
    return (
      <div className="card alert success" role="status" aria-live="polite">
        <h2>Booking confirmed</h2>
        <p>
          Your booking reference is <span className="reference">{reference}</span>.
        </p>
        <p>Payment was simulated - no real money was charged.</p>
        <Link className="button" to="/bookings">
          View my bookings
        </Link>
      </div>
    );
  }

  if (step === 'idle') {
    return (
      <div>
        <button type="button" className="button" onClick={() => setStep('confirm')}>
          Book this gig
        </button>
      </div>
    );
  }

  const sending = step === 'sending';

  return (
    <div className="card confirm-panel" role="region" aria-labelledby="confirm-booking-title">
      <h2 id="confirm-booking-title">Confirm your booking</h2>
      <dl className="detail-list">
        <dt>Gig</dt>
        <dd>{title}</dd>
        <dt>Price</dt>
        <dd>{formatMoney(price)}</dd>
      </dl>
      <p className="alert info">Payment is simulated. You won&apos;t be charged any real money.</p>

      <div aria-live="assertive">
        {error && (
          <p className="alert error" role="alert">
            {error}
          </p>
        )}
      </div>

      <div className="button-row">
        <button type="button" className="button" onClick={confirmBooking} disabled={sending}>
          {sending ? 'Booking…' : 'Confirm booking'}
        </button>
        <button
          type="button"
          className="button secondary"
          onClick={() => {
            setStep('idle');
            setError('');
          }}
          disabled={sending}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

/**
 * An inline "are you sure?" step for destructive actions (delete a gig).
 * Rendered in place of the button that opened it, with the question
 * announced to screen readers.
 */
export default function ConfirmAction({ title, children, confirmLabel, busyLabel, busy, error, onConfirm, onCancel }) {
  return (
    <div className="card confirm-panel" role="alertdialog" aria-labelledby="confirm-action-title">
      <h2 id="confirm-action-title">{title}</h2>
      {children}

      <div aria-live="assertive">
        {error && (
          <p className="alert error" role="alert">
            {error}
          </p>
        )}
      </div>

      <div className="button-row">
        <button type="button" className="button danger" onClick={onConfirm} disabled={busy}>
          {busy ? busyLabel : confirmLabel}
        </button>
        <button type="button" className="button secondary" onClick={onCancel} disabled={busy}>
          Cancel
        </button>
      </div>
    </div>
  );
}

/**
 * A labelled input with an optional hint and an inline error.
 *
 * The error sits in an aria-live region that's always rendered, so screen
 * readers announce it as soon as it appears, and the input points at it
 * with aria-describedby / aria-invalid. Pass as="textarea" for long text.
 */
export default function FormField({ id, label, error, hint, className = '', as: Control = 'input', ...inputProps }) {
  const hintId = hint ? `${id}-hint` : undefined;
  const errorId = `${id}-error`;
  const describedBy = [hintId, error ? errorId : null].filter(Boolean).join(' ') || undefined;

  return (
    <div className={`field ${className}`.trim()}>
      <label htmlFor={id}>{label}</label>
      <Control id={id} aria-invalid={error ? 'true' : 'false'} aria-describedby={describedBy} {...inputProps} />
      {hint && (
        <span id={hintId} className="field-hint">
          {hint}
        </span>
      )}
      <span id={errorId} className="field-error" aria-live="polite">
        {error}
      </span>
    </div>
  );
}

import { Link } from 'react-router-dom';
import { formatCategory, formatDays, formatMoney } from '../utils/format';
import { decodeEntities } from '../utils/text';

// All text from the API is decoded for display and rendered as plain text
// by React - never as HTML.
export default function GigCard({ gig }) {
  const title = decodeEntities(gig.title);
  const freelancerName = gig.freelancer ? decodeEntities(gig.freelancer.name) : 'Unknown freelancer';

  return (
    <article className="card gig-card">
      <h2>
        <Link to={`/gigs/${gig.id}`}>{title}</Link>
      </h2>
      <ul className="gig-meta">
        <li>{formatCategory(decodeEntities(gig.category))}</li>
        <li>Delivery in {formatDays(gig.deliveryDays)}</li>
        <li>by {freelancerName}</li>
      </ul>
      <p className="price">{formatMoney(gig.price)}</p>
    </article>
  );
}

import { useRef, useState } from 'react';
import { GIG_CATEGORIES, MAX_PRICE } from '../utils/constants';
import { formatCategory } from '../utils/format';
import { validateGig } from '../utils/validation';
import FormField from './FormField';

const EMPTY_GIG = { title: '', description: '', price: '', category: '', deliveryDays: '' };

function messageFor(err) {
  if (err.status === 403) return 'You can only change your own gigs.';
  if (err.status === 404) return 'This gig no longer exists.';
  return err.message;
}

/**
 * Shared by "New gig" and "Edit gig".
 *
 * initialValues must be PLAIN text (already run through decodeEntities when
 * editing). What the user typed is sent as-is and the API escapes it once,
 * so text like "Tom & Jerry's" never turns into "Tom &amp;amp; Jerry".
 * Price and delivery days are sent as real numbers.
 */
export default function GigForm({ initialValues = EMPTY_GIG, submitLabel, busyLabel, onSubmit }) {
  const [form, setForm] = useState(initialValues);
  const [errors, setErrors] = useState({});
  const [formError, setFormError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const submittingRef = useRef(false);

  function update(field) {
    return (event) => setForm((current) => ({ ...current, [field]: event.target.value }));
  }

  async function handleSubmit(event) {
    event.preventDefault();
    if (submittingRef.current) return;

    const { errors: fieldErrors, values } = validateGig(form, { categories: GIG_CATEGORIES, maxPrice: MAX_PRICE });
    setErrors(fieldErrors);
    setFormError('');
    if (Object.keys(fieldErrors).length > 0) return;

    submittingRef.current = true;
    setSubmitting(true);
    try {
      await onSubmit(values);
    } catch (err) {
      setFormError(messageFor(err));
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }

  return (
    <form className="form card" onSubmit={handleSubmit} noValidate>
      <div aria-live="assertive">
        {formError && (
          <p className="alert error" role="alert">
            {formError}
          </p>
        )}
      </div>

      <FormField
        id="gig-title"
        label="Title"
        value={form.title}
        onChange={update('title')}
        error={errors.title}
        hint="3 to 100 characters"
        maxLength={100}
        required
      />
      <FormField
        id="gig-description"
        as="textarea"
        label="Description"
        value={form.description}
        onChange={update('description')}
        error={errors.description}
        hint="10 to 1000 characters"
        maxLength={1000}
        required
      />

      <div className="form-grid-2">
        <FormField
          id="gig-price"
          label="Price (R)"
          inputMode="decimal"
          value={form.price}
          onChange={update('price')}
          error={errors.price}
          hint="1 to 100000, up to 2 decimals"
          required
        />
        <FormField
          id="gig-delivery-days"
          label="Delivery days"
          inputMode="numeric"
          value={form.deliveryDays}
          onChange={update('deliveryDays')}
          error={errors.deliveryDays}
          hint="Whole days, 1 to 90"
          required
        />
        <div className="field">
          <label htmlFor="gig-category">Category</label>
          <select
            id="gig-category"
            value={form.category}
            onChange={update('category')}
            aria-invalid={errors.category ? 'true' : 'false'}
            aria-describedby={errors.category ? 'gig-category-error' : undefined}
            required
          >
            <option value="">Choose a category</option>
            {GIG_CATEGORIES.map((category) => (
              <option key={category} value={category}>
                {formatCategory(category)}
              </option>
            ))}
          </select>
          <span id="gig-category-error" className="field-error" aria-live="polite">
            {errors.category}
          </span>
        </div>
      </div>

      <div className="button-row">
        <button type="submit" className="button" disabled={submitting}>
          {submitting ? busyLabel : submitLabel}
        </button>
      </div>
    </form>
  );
}

import { useState } from 'react';
import { formatMoney, formatMonth, formatWholeRand } from '../utils/format';

/**
 * Monthly income bar chart, drawn as plain SVG.
 *
 * Works under the strict CSP (style-src 'self', no 'unsafe-inline'): the
 * chart uses only SVG geometry attributes and classes from global.css, no
 * inline style attributes, no chart library, and no dangerouslySetInnerHTML.
 *
 * Accessibility: the SVG has role="img" with an aria-label summary, and the
 * same figures are in a visually hidden table for screen readers.
 */

const WIDTH = 720;
const HEIGHT = 260;
const PAD = { top: 28, right: 12, bottom: 32, left: 72 };
const PLOT_W = WIDTH - PAD.left - PAD.right;
const PLOT_H = HEIGHT - PAD.top - PAD.bottom;
const TICKS = 4;

// A round step (1, 2, 2.5 or 5 x 10^n) so the axis reads R 0, R 250, R 500...
function niceStep(max) {
  if (!(max > 0)) return 1;
  const raw = max / TICKS;
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const normalised = raw / magnitude;
  const factor = [1, 2, 2.5, 5, 10].find((f) => normalised <= f);
  return factor * magnitude;
}

// Bar with a 4px rounded top and a square bottom on the baseline.
function barPath(x, y, w, h) {
  const r = Math.min(4, w / 2, h);
  return `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z`;
}

function summary(monthly) {
  const first = monthly[0];
  const last = monthly[monthly.length - 1];
  const best = monthly.reduce((top, m) => (m.income > top.income ? m : top), monthly[0]);
  const range = `${formatMonth(first.month)} to ${formatMonth(last.month)}`;
  if (!best || best.income <= 0) return `Bar chart of monthly income, ${range}. No income in any month.`;
  return (
    `Bar chart of monthly income, ${range}. Highest month: ${formatMonth(best.month)} ` +
    `with ${formatMoney(best.income)}. Full figures are in the table that follows.`
  );
}

export default function MonthlyIncomeChart({ monthly }) {
  const [active, setActive] = useState(null);
  if (!Array.isArray(monthly) || monthly.length === 0) return null;

  const max = Math.max(...monthly.map((m) => m.income));
  const step = niceStep(max);
  const yMax = Math.max(step, Math.ceil(max / step) * step);
  const ticks = [];
  for (let value = 0; value <= yMax + step / 2; value += step) ticks.push(value);

  const band = PLOT_W / monthly.length;
  const barWidth = Math.min(32, band * 0.6);
  const y = (value) => PAD.top + PLOT_H - (value / yMax) * PLOT_H;
  const baseline = y(0);

  return (
    <figure className="chart">
      <div className="chart-scroll">
        <svg
          className="chart-svg"
          viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
          role="img"
          aria-label={summary(monthly)}
          onMouseLeave={() => setActive(null)}
        >
          <g aria-hidden="true">
            {ticks.map((value) => (
              <g key={value}>
                <line
                  className={value === 0 ? 'chart-baseline' : 'chart-grid'}
                  x1={PAD.left}
                  x2={WIDTH - PAD.right}
                  y1={y(value)}
                  y2={y(value)}
                />
                <text className="chart-axis-label" x={PAD.left - 8} y={y(value)} textAnchor="end" dominantBaseline="middle">
                  {formatWholeRand(value)}
                </text>
              </g>
            ))}

            {monthly.map((m, i) => {
              const x = PAD.left + i * band + (band - barWidth) / 2;
              const top = y(m.income);
              const isActive = active === i;
              return (
                <g key={m.month}>
                  {m.income > 0 && (
                    <path
                      className={`chart-bar${isActive ? ' active' : ''}`}
                      d={barPath(x, top, barWidth, baseline - top)}
                      data-testid="chart-bar"
                    />
                  )}
                  <text className="chart-axis-label" x={x + barWidth / 2} y={HEIGHT - PAD.bottom + 18} textAnchor="middle">
                    {formatMonth(m.month).slice(0, 3)}
                  </text>
                  {isActive && (
                    <text className="chart-value-label" x={x + barWidth / 2} y={Math.max(top - 8, 14)} textAnchor="middle">
                      {formatMoney(m.income)} · {m.bookings} {m.bookings === 1 ? 'booking' : 'bookings'}
                    </text>
                  )}
                  {/* Hit area wider and taller than the bar, so hovering is easy. */}
                  <rect
                    className="chart-hit"
                    x={PAD.left + i * band}
                    y={PAD.top}
                    width={band}
                    height={PLOT_H}
                    onMouseEnter={() => setActive(i)}
                  >
                    <title>{`${formatMonth(m.month)}: ${formatMoney(m.income)}`}</title>
                  </rect>
                </g>
              );
            })}
          </g>
        </svg>
      </div>

      <table className="visually-hidden">
        <caption>Monthly income for the tax year</caption>
        <thead>
          <tr>
            <th scope="col">Month</th>
            <th scope="col">Income</th>
            <th scope="col">Bookings</th>
          </tr>
        </thead>
        <tbody>
          {monthly.map((m) => (
            <tr key={m.month}>
              <th scope="row">{formatMonth(m.month)}</th>
              <td>{formatMoney(m.income)}</td>
              <td>{m.bookings}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  );
}

export default function Pagination({ page, totalPages, onChange, disabled = false }) {
  if (totalPages <= 1) return null;

  return (
    <nav className="pagination" aria-label="Pagination">
      <button
        type="button"
        className="button secondary"
        onClick={() => onChange(page - 1)}
        disabled={disabled || page <= 1}
      >
        Previous
      </button>
      <span aria-live="polite">
        Page {page} of {totalPages}
      </span>
      <button
        type="button"
        className="button secondary"
        onClick={() => onChange(page + 1)}
        disabled={disabled || page >= totalPages}
      >
        Next
      </button>
    </nav>
  );
}

import { Navigate, Outlet, useLocation } from 'react-router-dom';
import useAuth from '../context/useAuth';
import NotAllowed from '../pages/NotAllowed';
import { LoadingState } from './StatusMessage';

/**
 * Wraps routes that need a logged-in user. With `roles`, only those roles
 * get through; anyone else sees a clear "not allowed" page.
 *
 * This only shapes the UI. The API enforces the same rules on every request,
 * so hiding a page here is never the thing keeping data safe.
 */
export default function ProtectedRoute({ roles, children }) {
  const { user, loading } = useAuth();
  const location = useLocation();

  if (loading) {
    return <LoadingState label="Checking your session…" />;
  }

  if (!user) {
    return <Navigate to="/login" replace state={{ from: `${location.pathname}${location.search}` }} />;
  }

  if (roles && !roles.includes(user.role)) {
    return <NotAllowed />;
  }

  return children ?? <Outlet />;
}

// Shared loading, error and empty states so every page behaves the same way.

export function LoadingState({ label = 'Loading…' }) {
  return (
    <p className="status" role="status" aria-live="polite">
      {label}
    </p>
  );
}

export function ErrorState({ message, onRetry }) {
  return (
    <div className="alert error" role="alert">
      <p>{message}</p>
      {onRetry && (
        <button type="button" className="button secondary" onClick={onRetry}>
          Try again
        </button>
      )}
    </div>
  );
}

export function EmptyState({ title, children }) {
  return (
    <div className="card status">
      <h2>{title}</h2>
      {children}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { fetchCurrentUser, loginRequest, registerRequest } from '../api/auth';
import { setUnauthorizedHandler } from '../api/client';
import { clearToken, readToken, saveToken } from '../utils/storage';
import { AuthContext } from './authContext';

// Only what the UI needs. The email isn't kept (it's only ever in the login
// and register forms) and the token stays in storage, never in state.
function toSessionUser(user) {
  return { id: user.id, name: user.name, role: user.role };
}

export default function AuthProvider({ children }) {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  // Only "loading" if there's a stored token to check.
  const [loading, setLoading] = useState(() => Boolean(readToken()));

  // On start-up, check the stored token with the API and load the user.
  useEffect(() => {
    if (!readToken()) return undefined;

    const controller = new AbortController();
    fetchCurrentUser(controller.signal)
      .then((data) => setUser(toSessionUser(data.user)))
      .catch((err) => {
        if (err.name === 'AbortError') return;
        if (err.status === 401) clearToken(); // expired or invalid token
        setUser(null);
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });

    return () => controller.abort();
  }, []);

  // Any later 401 on a protected call: the session is gone, so log out and
  // go to the login page (api/client.js has already cleared the token).
  useEffect(() => {
    setUnauthorizedHandler(() => {
      setUser(null);
      navigate('/login', { replace: true, state: { expired: true } });
    });
    return () => setUnauthorizedHandler(null);
  }, [navigate]);

  const login = useCallback(async (email, password) => {
    const data = await loginRequest(email, password);
    saveToken(data.token);
    const sessionUser = toSessionUser(data.user);
    setUser(sessionUser);
    return sessionUser;
  }, []);

  const register = useCallback(async (details) => {
    const data = await registerRequest(details);
    saveToken(data.token);
    const sessionUser = toSessionUser(data.user);
    setUser(sessionUser);
    return sessionUser;
  }, []);

  const logout = useCallback(() => {
    clearToken();
    setUser(null);
    navigate('/login', { replace: true });
  }, [navigate]);

  const value = useMemo(
    () => ({ user, loading, login, register, logout }),
    [user, loading, login, register, logout]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

import { Link, useNavigate, useParams } from 'react-router-dom';
import { createGig, getGig, isValidId, updateGig } from '../api/gigs';
import GigForm from '../components/GigForm';
import { ErrorState, LoadingState } from '../components/StatusMessage';
import useAuth from '../context/useAuth';
import { decodeEntities } from '../utils/text';
import useApiData from '../utils/useApiData';

const noGig = () => Promise.resolve(null);

// API text is escaped; the form needs the plain text the freelancer typed.
function toFormValues(gig) {
  return {
    title: decodeEntities(gig.title),
    description: decodeEntities(gig.description),
    price: String(gig.price),
    category: decodeEntities(gig.category),
    deliveryDays: String(gig.deliveryDays),
  };
