import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { CSP, CSP_HEADER, SECURITY_HEADERS, toNginxHeaders } from '../../securityHeaders.js';
import viteConfig from '../../vite.config.js';

// Guards the "one source of truth" for the client's security headers:
// the build's <meta> CSP, `npm run preview` and nginx in Docker.
// Vitest runs from the client folder (where vite.config.js is).
const nginxConf = readFileSync(resolve(process.cwd(), 'nginx.conf'), 'utf8');
const SNIPPET = 'include /etc/nginx/snippets/security-headers.conf;';

// "location /assets/ { ... }" blocks, keyed by their path.
function locationBlocks(conf) {
  const blocks = {};
  for (const match of conf.matchAll(/location\s+(=\s+)?(\S+)\s*\{([^}]*)\}/g)) {
    blocks[match[2]] = match[3];
  }
  return blocks;
}

describe('client security headers', () => {
  it('has a strict CSP with frame-ancestors in the header version', () => {
    expect(CSP).toContain("default-src 'self'");
    expect(CSP).not.toMatch(/unsafe-inline|unsafe-eval/);
    expect(CSP).not.toContain('frame-ancestors'); // ignored in a <meta> tag
    expect(CSP_HEADER).toBe(`${CSP}; frame-ancestors 'none'`);
    expect(SECURITY_HEADERS['Content-Security-Policy']).toBe(CSP_HEADER);
  });

  it('includes the permissions and site isolation headers', () => {
    expect(SECURITY_HEADERS['Permissions-Policy']).toMatch(/camera=\(\)/);
    expect(SECURITY_HEADERS['Cross-Origin-Resource-Policy']).toBe('same-origin');
    expect(SECURITY_HEADERS['Cross-Origin-Opener-Policy']).toBe('same-origin');
    expect(SECURITY_HEADERS['Cross-Origin-Embedder-Policy']).toBe('require-corp');
  });

  it('npm run preview sends exactly the shared headers', () => {
    expect(viteConfig.preview.headers).toEqual(SECURITY_HEADERS);
  });

  it('generates one nginx add_header line per header, with the same values', () => {
    const lines = toNginxHeaders()
      .split('\n')
      .filter((line) => line.startsWith('add_header'));
    expect(lines).toHaveLength(Object.keys(SECURITY_HEADERS).length);
    for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
      expect(lines).toContain(`add_header ${name} "${value}" always;`);
    }
  });

  it('refuses to write a header value that would break the nginx config', () => {
    expect(() => toNginxHeaders({ 'X-Test': 'a"; evil' })).toThrow();
    expect(() => toNginxHeaders({ 'X-Test': 'line\nbreak' })).toThrow();
    expect(() => toNginxHeaders({ 'Bad Name': 'x' })).toThrow();
  });

  it('nginx includes the generated headers wherever it serves files', () => {
    const blocks = locationBlocks(nginxConf);
    expect(Object.keys(blocks)).toEqual(expect.arrayContaining(['/', '/assets/', '/api/']));
    expect(blocks['/']).toContain(SNIPPET);
    expect(blocks['/assets/']).toContain(SNIPPET);
    expect(blocks['/healthz']).toContain(SNIPPET);
    // The api sends its own Helmet headers.
    expect(blocks['/api/']).not.toContain(SNIPPET);
  });

  it('nginx never defines a security header by hand', () => {
    expect(nginxConf).not.toMatch(/add_header\s+(Content-Security-Policy|X-Frame-Options|X-Content-Type-Options|Referrer-Policy)/i);
    expect(nginxConf).toMatch(/server_tokens off;/);
  });

  it('nginx verifies the api certificate and passes the forwarding headers', () => {
    const api = locationBlocks(nginxConf)['/api/'];
    expect(api).toMatch(/proxy_ssl_verify on;/);
    expect(api).toMatch(/proxy_ssl_name api;/);
    expect(api).toMatch(/proxy_set_header Host \$host;/);
    expect(api).toMatch(/proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;/);
    expect(api).toMatch(/proxy_set_header X-Forwarded-Proto \$scheme;/);
  });
});

// A tax estimate shaped like GET /api/income/tax-estimate returns it. The
// default is the README worked example: R300 000 in the 2026/27 tax year.
const BRACKETS_2027 = [
  [0, 245100, 18],
  [245100, 383100, 26],
  [383100, 530200, 31],
  [530200, 695800, 36],
  [695800, 887000, 39],
  [887000, 1878600, 41],
  [1878600, null, 45],
];

function months(startYear) {
  return Array.from({ length: 12 }, (_, i) => {
    const month = ((2 + i) % 12) + 1;
    const year = month >= 3 ? startYear : startYear + 1;
    return `${year}-${String(month).padStart(2, '0')}`;
  });
}

export function makeTaxEstimate({ startYear = 2026, monthlyIncome = {}, totals, breakdown } = {}) {
  const income = { [`${startYear}-04`]: [100000.1, 3], [`${startYear + 1}-01`]: [199999.9, 5], ...monthlyIncome };
  return {
    taxYear: {
      label: `1 March ${startYear} to 28 February ${startYear + 1} (SARS ${startYear + 1} tax year)`,
      start: `${startYear}-03-01`,
      end: `${startYear + 1}-02-28`,
    },
    totals: totals || {
      gross: 300000,
      taxBeforeRebate: 58392,
      estimatedTax: 40572,
      takeHome: 259428,
      effectiveRatePercent: 13.52,
    },
    rebate: 17820,
    taxFreeThreshold: 99000,
    breakdown:
      breakdown ||
      BRACKETS_2027.map(([from, to, ratePercent], i) => ({
        from,
        to,
        ratePercent,
        amountInBracket: [245100, 54900][i] || 0,
        tax: [44118, 14274][i] || 0,
      })),
    monthly: months(startYear).map((month) => ({
      month,
      income: income[month] ? income[month][0] : 0,
      bookings: income[month] ? income[month][1] : 0,
    })),
    assumptions: ['Resident individual under 65, so only the primary rebate applies.', 'No deductions are taken into account.'],
    disclaimer: 'This is an estimate for planning only, not tax advice and not a SARS assessment.',
    source: {
      name: 'SARS - Rates of Tax for Individuals',
      url: 'https://www.sars.gov.za/tax-rates/income-tax/rates-of-tax-for-individuals/',
      checkedOn: '2026-11-07',
    },
    availableTaxYears: [2026, 2025, 2024, 2023],
  };
}

export const emptyTotals = { gross: 0, taxBeforeRebate: 0, estimatedTax: 0, takeHome: 0, effectiveRatePercent: 0 };

/**
 * The API HTML-escapes free text before saving it (validator's escape()),
 * so "Tom & Jerry" comes back as "Tom &amp; Jerry". decodeEntities turns
 * exactly those entities back into characters for display.
 *
 * It runs in a single pass, so "&amp;lt;" becomes "&lt;" (the text the
 * user actually typed), not "<". The result is only ever rendered by React
 * as a text node - never as HTML - so decoded "<img ...>" shows up as the
 * literal characters, not an element.
 */
const ENTITIES = {
  '&amp;': '&',
  '&lt;': '<',
  '&gt;': '>',
  '&quot;': '"',
  '&#x27;': "'",
  '&#x2F;': '/',
  '&#x5C;': '\\',
  '&#96;': '`',
};

const ENTITY_PATTERN = /&(?:amp|lt|gt|quot|#x27|#x2F|#x5C|#96);/g;

export function decodeEntities(value) {
  if (typeof value !== 'string') return '';
  return value.replace(ENTITY_PATTERN, (entity) => ENTITIES[entity]);
}

/**
 * Client-side checks that mirror api/src/middleware/validators.js, so most
 * mistakes are shown next to the field before anything is sent. The API
 * still validates everything - these are for convenience, not security.
 */

// A pragmatic email shape check; the API's isEmail() has the final say.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function validateRegister({ name, email, password, role }) {
  const errors = {};

  // API: trimmed, 2-60 characters
  if (!name) errors.name = 'Name is required';
  else if (name.length < 2 || name.length > 60) errors.name = 'Name must be 2-60 characters';

  // API: required, valid email
  if (!email) errors.email = 'Email is required';
  else if (!EMAIL_PATTERN.test(email)) errors.email = 'Must be a valid email address';

  // API: at least 8 characters with at least one number
  if (!password) errors.password = 'Password is required';
  else if (password.length < 8) errors.password = 'Password must be at least 8 characters';
  else if (!/\d/.test(password)) errors.password = 'Password must contain at least one number';

  // API: optional, client or freelancer only
  if (role !== 'client' && role !== 'freelancer') errors.role = 'Choose client or freelancer';

  return errors;
}

export function validateLogin({ email, password }) {
  const errors = {};
  if (!email) errors.email = 'Email is required';
  else if (!EMAIL_PATTERN.test(email)) errors.email = 'Must be a valid email address';
  if (!password) errors.password = 'Password is required';
  return errors;
}

// Gig list price filters: optional, 0 to max, min not above max.
export function validatePriceRange(minPrice, maxPrice, maxAllowed) {
  const errors = {};
  const min = minPrice === '' ? null : Number(minPrice);
  const max = maxPrice === '' ? null : Number(maxPrice);

  if (min !== null && (!Number.isFinite(min) || min < 0 || min > maxAllowed)) {
    errors.minPrice = `Enter a price from 0 to ${maxAllowed}`;
  }
  if (max !== null && (!Number.isFinite(max) || max < 0 || max > maxAllowed)) {
    errors.maxPrice = `Enter a price from 0 to ${maxAllowed}`;
  }
  if (!errors.minPrice && !errors.maxPrice && min !== null && max !== null && min > max) {
    errors.maxPrice = 'Max price must be at least the min price';
  }
  return errors;
}

/**
 * Gig form, mirroring api/src/middleware/gigValidators.js. Takes the raw
 * form strings and returns { errors, values } where values has trimmed text
 * and REAL numbers for price and deliveryDays - the API rejects "150" as a
 * string, so nothing is sent until these convert cleanly.
 */
export function validateGig(form, { categories, maxPrice }) {
  const errors = {};
  const title = form.title.trim();
  const description = form.description.trim();
  const category = form.category;
  const priceText = String(form.price).trim();
  const daysText = String(form.deliveryDays).trim();

  // API: 3-100 characters after trimming
  if (title.length < 3 || title.length > 100) errors.title = 'Title must be 3-100 characters';

  // API: 10-1000 characters after trimming
  if (description.length < 10 || description.length > 1000) {
    errors.description = 'Description must be 10-1000 characters';
  }

  // API: a number from 1 to 100000 with at most 2 decimal places
  const price = Number(priceText);
  if (priceText === '') errors.price = 'Price is required';
  else if (!/^\d+(\.\d{1,2})?$/.test(priceText) || !Number.isFinite(price)) {
    errors.price = 'Enter a price like 150 or 149.99';
  } else if (price < 1 || price > maxPrice) errors.price = `Price must be between 1 and ${maxPrice}`;

  // API: a whole number from 1 to 90
  const deliveryDays = Number(daysText);
  if (daysText === '') errors.deliveryDays = 'Delivery days is required';
  else if (!/^\d+$/.test(daysText) || deliveryDays < 1 || deliveryDays > 90) {
    errors.deliveryDays = 'Delivery days must be a whole number from 1 to 90';
  }

  // API: one of the fixed categories
  if (!categories.includes(category)) errors.category = 'Choose a category';

  return { errors, values: { title, description, price, category, deliveryDays } };
}
